const PREFIX = 'pst.async.';
const memory = new Map<string, string>();

function storage() {
  try {
    if (typeof sessionStorage === 'undefined') {
      return undefined;
    }
    return sessionStorage;
  } catch {
    return undefined;
  }
}

function readRaw(key: string) {
  const prefixed = PREFIX + key;
  const session = storage();
  if (session) {
    try {
      const stored = session.getItem(prefixed);
      if (stored !== null) {
        memory.set(key, stored);
        return stored;
      }
    } catch {
      // Fall through to the in-memory copy.
    }
  }
  return memory.has(key) ? (memory.get(key) ?? null) : null;
}

function writeRaw(key: string, value: string) {
  memory.set(key, value);
  const session = storage();
  if (!session) {
    return;
  }
  const prefixed = PREFIX + key;
  try {
    session.setItem(prefixed, value);
  } catch {
    try {
      session.removeItem(prefixed);
    } catch {
      // Memory remains the source of truth for this tab.
    }
  }
}

function removeRaw(key: string) {
  memory.delete(key);
  const session = storage();
  if (!session) {
    return;
  }
  try {
    session.removeItem(PREFIX + key);
  } catch {
    // The in-memory entry is already gone.
  }
}

const AsyncStorage = {
  async getItem(key: string) {
    return readRaw(key);
  },
  async setItem(key: string, value: string) {
    writeRaw(key, value);
  },
  async removeItem(key: string) {
    removeRaw(key);
  },
  async mergeItem(key: string, value: string) {
    const current = readRaw(key);
    let next = value;
    try {
      const base = current ? (JSON.parse(current) as Record<string, unknown>) : {};
      const patch = JSON.parse(value) as Record<string, unknown>;
      next = JSON.stringify({ ...base, ...patch });
    } catch {
      next = value;
    }
    writeRaw(key, next);
  },
  async clear() {
    for (const key of [...memory.keys()]) {
      removeRaw(key);
    }
  },
  async getAllKeys() {
    const session = storage();
    if (session) {
      try {
        for (let index = 0; index < session.length; index += 1) {
          const storedKey = session.key(index);
          if (storedKey?.startsWith(PREFIX)) {
            const key = storedKey.slice(PREFIX.length);
            const value = session.getItem(storedKey);
            if (value !== null) {
              memory.set(key, value);
            }
          }
        }
      } catch {
        // Use whatever is already in memory.
      }
    }
    return [...memory.keys()];
  },
  async multiGet(keys: readonly string[]) {
    const entries: [string, string | null][] = [];
    for (const key of keys) {
      entries.push([key, readRaw(key)]);
    }
    return entries;
  },
  async multiSet(entries: readonly (readonly [string, string])[]) {
    for (const [key, value] of entries) {
      writeRaw(key, value);
    }
  },
  async multiRemove(keys: readonly string[]) {
    for (const key of keys) {
      removeRaw(key);
    }
  },
};

export default AsyncStorage;

import type { ImageSourcePropType } from 'react-native';

export const BUNDLED_PET_IMAGES: Record<string, ImageSourcePropType> = {
  'LilMama.jpeg': require('../../assets/images/pets/LilMama.jpeg'),
  'LilMama2.jpeg': require('../../assets/images/pets/LilMama2.jpeg'),
  'Louie.jpeg': require('../../assets/images/pets/Louie.jpeg'),
  'Louie2.jpeg': require('../../assets/images/pets/Louie2.jpeg'),
  'Mia.jpeg': require('../../assets/images/pets/Mia.jpeg'),
  'Mrs Frizzle.jpg': require('../../assets/images/pets/Mrs Frizzle.jpg'),
  'Nala.jpeg': require('../../assets/images/pets/Nala.jpeg'),
  'Nora.jpeg': require('../../assets/images/pets/Nora.jpeg'),
  'Tippy.jpeg': require('../../assets/images/pets/Tippy.jpeg'),
};

export function normalizePetAssetKey(uri: string): string {
  if (!uri) {
    return '';
  }
  return uri
    .replace(/^asset:/i, '')
    .replace(/^bundled:/i, '')
    .replace(/^assets\/images\/pets\//i, '')
    .replace(/^\/?images\/pets\//i, '')
    .trim();
}

export function isBundledPetImageKey(uri: string): boolean {
  if (!uri) {
    return false;
  }
  const normalized = normalizePetAssetKey(uri);
  return normalized in BUNDLED_PET_IMAGES;
}

export function resolvePetImageSource(
  photoUri: string | null | undefined
): ImageSourcePropType | null {
  if (!photoUri) {
    return null;
  }

  const normalized = normalizePetAssetKey(photoUri);
  if (normalized in BUNDLED_PET_IMAGES) {
    return BUNDLED_PET_IMAGES[normalized];
  }

  if (
    photoUri.startsWith('file:') ||
    photoUri.startsWith('content:') ||
    photoUri.startsWith('ph:') ||
    photoUri.startsWith('blob:') ||
    photoUri.startsWith('http:') ||
    photoUri.startsWith('https:') ||
    photoUri.startsWith('data:')
  ) {
    return { uri: photoUri };
  }

  return null;
}

export function getBundledPetImageKeys(): string[] {
  return Object.keys(BUNDLED_PET_IMAGES);
}

import { Directory, File, Paths } from 'expo-file-system';

import { isBundledPetImageKey } from './pet-assets';

const PET_IMAGE_DIRECTORY = new Directory(Paths.document, 'pet-show-and-tell-images');

export async function copyPetImageIntoAppStorage(sourceUri: string) {
  if (
    sourceUri.startsWith('seed:') ||
    sourceUri.startsWith('asset:') ||
    sourceUri.startsWith('bundled:') ||
    isBundledPetImageKey(sourceUri)
  ) {
    return sourceUri;
  }

  PET_IMAGE_DIRECTORY.create({ idempotent: true, intermediates: true });
  const cleanUri = sourceUri.split('?')[0] ?? sourceUri;
  const maybeExtension = cleanUri.split('.').pop()?.toLowerCase();
  const extension =
    maybeExtension && ['jpg', 'jpeg', 'png', 'webp', 'heic'].includes(maybeExtension)
      ? maybeExtension
      : 'jpg';
  const destination = new File(
    PET_IMAGE_DIRECTORY,
    'pet-photo-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7) + '.' + extension
  );
  await new File(sourceUri).copy(destination);
  return destination.uri;
}

import { isBundledPetImageKey } from './pet-assets';

function readBlobAsDataUrl(blob: Blob) {
  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => {
      reject(new Error('This picture could not be saved in the browser preview.'));
    };
    reader.onload = () => {
      if (typeof reader.result === 'string' && reader.result.startsWith('data:')) {
        resolve(reader.result);
        return;
      }
      reject(new Error('This picture could not be saved in the browser preview.'));
    };
    reader.readAsDataURL(blob);
  });
}

export async function copyPetImageIntoAppStorage(sourceUri: string) {
  if (
    sourceUri.startsWith('seed:') ||
    sourceUri.startsWith('asset:') ||
    sourceUri.startsWith('bundled:') ||
    sourceUri.startsWith('data:') ||
    isBundledPetImageKey(sourceUri)
  ) {
    return sourceUri;
  }

  if (sourceUri.startsWith('blob:')) {
    const response = await fetch(sourceUri);
    if (!response.ok) {
      throw new Error('This picture could not be saved in the browser preview.');
    }
    return readBlobAsDataUrl(await response.blob());
  }

  throw new Error('This picture could not be saved in the browser preview.');
}

import * as SQLite from 'expo-sqlite';

import {
  INITIAL_SEEDED_PETS,
  INITIAL_SEEDED_POSTS,
  KNOWN_LEGACY_SEED_PET_IDS,
  KNOWN_LEGACY_SEED_POST_IDS,
} from '../data/pet-seed';
import type {
  Pet,
  PetPost,
  PetPostInput,
  PetProfileInput,
  PetSnapshot,
  ReactionKind,
} from '../types/pet';

const DATABASE_NAME = 'pet-show-and-tell.db';

interface PetRow extends Omit<Pet, 'isUserPet'> {
  isUserPet: number;
}

let databasePromise: Promise<SQLite.SQLiteDatabase> | undefined;
let initializationPromise: Promise<void> | undefined;

function getDatabase() {
  databasePromise ??= SQLite.openDatabaseAsync(DATABASE_NAME);
  return databasePromise;
}

export function createLocalId(prefix: string) {
  return prefix + '-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);
}

export async function initializePetDatabase() {
  initializationPromise ??= (async () => {
    const database = await getDatabase();
    await database.execAsync(
      [
        'PRAGMA foreign_keys = ON;',
        'CREATE TABLE IF NOT EXISTS pets (',
        '  id TEXT PRIMARY KEY NOT NULL,',
        '  name TEXT NOT NULL,',
        '  species TEXT NOT NULL,',
        '  photoUri TEXT NOT NULL,',
        '  description TEXT NOT NULL,',
        '  createdAt TEXT NOT NULL,',
        '  isUserPet INTEGER NOT NULL DEFAULT 0',
        ');',
        'CREATE TABLE IF NOT EXISTS posts (',
        '  id TEXT PRIMARY KEY NOT NULL,',
        '  petId TEXT NOT NULL,',
        '  photoUri TEXT NOT NULL,',
        '  description TEXT NOT NULL,',
        '  createdAt TEXT NOT NULL,',
        '  FOREIGN KEY (petId) REFERENCES pets(id) ON DELETE CASCADE',
        ');',
        'CREATE TABLE IF NOT EXISTS reactions (',
        '  postId TEXT PRIMARY KEY NOT NULL,',
        "  value TEXT NOT NULL CHECK (value IN ('like', 'love')),",
        '  FOREIGN KEY (postId) REFERENCES posts(id) ON DELETE CASCADE',
        ');',
        'CREATE TABLE IF NOT EXISTS app_migrations (',
        '  id TEXT PRIMARY KEY NOT NULL',
        ');',
      ].join('\n')
    );

    await database.withTransactionAsync(async () => {
      const updateSeedCaptions = async () => {
        const done = await database.getFirstAsync<{ id: string }>(
          'SELECT id FROM app_migrations WHERE id = ?',
          'seed-captions-v1'
        );
        if (done) return;
        const v1Captions: Record<string, string> = {
          'post-nora-1': 'A cozy moment with Nora.',
          'post-mia-1': 'A little moment with Mia.',
          'post-mrs-frizzle-1': 'Meet Mrs Frizzle.',
          'post-nala-1': 'Meet Nala.',
          'post-lil-mama-1': "A moment with Lil' Mama.",
          'post-louie-1': 'A moment with Louie.',
          'post-tippy-1': 'A moment with Tippy.',
        };
        const oldCaptions: Record<string, string> = {
          'post-nora-1': 'Sweet princess dog that likes to sleep in and bake in the sun.',
          'post-mia-1': 'Little dog with a big personality.',
          'post-mrs-frizzle-1': 'Likes to dig.',
          'post-nala-1': 'Likes to climb.',
          'post-lil-mama-1': 'A wiggle worm that has a heart of gold.',
          'post-louie-1': 'Karuma as a dog but a cuddly bear at the same time.',
          'post-tippy-1': 'Crazy and sweet.',
        };
        for (const [postId, oldCaption] of Object.entries(oldCaptions)) {
          const nextCaption = v1Captions[postId];
          if (nextCaption) {
            await database.runAsync(
              'UPDATE posts SET description = ? WHERE id = ? AND description = ?',
              nextCaption,
              postId,
              oldCaption
            );
          }
        }
        await database.runAsync('INSERT INTO app_migrations (id) VALUES (?)', 'seed-captions-v1');
      };
      const applySeedUpdatesV2 = async () => {
        const done = await database.getFirstAsync<{ id: string }>(
          'SELECT id FROM app_migrations WHERE id = ?',
          'seed-v2'
        );
        if (done) return;

        await database.runAsync(
          "UPDATE pets SET photoUri = 'asset:Mrs Frizzle.jpg' WHERE id = 'pet-mrs-frizzle' AND photoUri = 'asset:Mrs Frizzle.jpeg'"
        );
        await database.runAsync(
          "UPDATE posts SET photoUri = 'asset:Mrs Frizzle.jpg' WHERE id = 'post-mrs-frizzle-1' AND photoUri = 'asset:Mrs Frizzle.jpeg'"
        );
        await database.runAsync(
          "UPDATE pets SET isUserPet = 0 WHERE id IN ('pet-mia', 'pet-tippy') AND isUserPet = 1"
        );

        const previousCaptions: Record<string, string[]> = {
          'post-nora-1': [
            'Sweet princess dog that likes to sleep in and bake in the sun.',
            'A cozy moment with Nora.',
          ],
          'post-mia-1': ['Little dog with a big personality.', 'A little moment with Mia.'],
          'post-mrs-frizzle-1': ['Likes to dig.', 'Meet Mrs Frizzle.'],
          'post-nala-1': ['Likes to climb.', 'Meet Nala.'],
          'post-lil-mama-1': [
            'A wiggle worm that has a heart of gold.',
            "A moment with Lil' Mama.",
          ],
          'post-lil-mama-2': ['Happy wiggles and sunny smiles.'],
          'post-louie-1': [
            'Karuma as a dog but a cuddly bear at the same time.',
            'A moment with Louie.',
          ],
          'post-louie-2': ['Full cuddly bear mode in his favorite cozy spot.'],
          'post-tippy-1': ['Crazy and sweet.'],
        };
        for (const post of INITIAL_SEEDED_POSTS) {
          const legacyCaptions = previousCaptions[post.id];
          if (!legacyCaptions?.length) continue;
          const placeholders = legacyCaptions.map(() => '?').join(', ');
          await database.runAsync(
            `UPDATE posts SET description = ? WHERE id = ? AND description IN (${placeholders})`,
            post.caption,
            post.id,
            ...legacyCaptions
          );
        }

        await database.runAsync('INSERT INTO app_migrations (id) VALUES (?)', 'seed-v2');
      };
      const applied = await database.getFirstAsync<{ id: string }>(
        'SELECT id FROM app_migrations WHERE id = ?',
        'personal-pets-v1'
      );
      if (applied) {
        const captionFixed = await database.getFirstAsync<{ id: string }>(
          'SELECT id FROM app_migrations WHERE id = ?',
          'louie-caption-v1'
        );
        if (!captionFixed) {
          await database.runAsync(
            'UPDATE posts SET description = ? WHERE id = ? AND description = ?',
            'Another moment with Louie.',
            'post-louie-2',
            'Full cuddly bear mode in his favorite cozy spot.'
          );
          await database.runAsync('INSERT INTO app_migrations (id) VALUES (?)', 'louie-caption-v1');
        }
        await updateSeedCaptions();
        await applySeedUpdatesV2();
        return;
      }
      // 1. Remove legacy sample seeds idempotently, preserving user-created records and reactions
      for (const legacyPostId of KNOWN_LEGACY_SEED_POST_IDS) {
        await database.runAsync(
          'DELETE FROM posts WHERE id = ? AND NOT EXISTS ' +
            '(SELECT 1 FROM reactions WHERE reactions.postId = posts.id) ' +
            'AND EXISTS (SELECT 1 FROM pets WHERE pets.id = posts.petId AND pets.isUserPet = 0)',
          legacyPostId
        );
      }
      for (const legacyPetId of KNOWN_LEGACY_SEED_PET_IDS) {
        await database.runAsync(
          'DELETE FROM pets WHERE id = ? AND isUserPet = 0 ' +
            'AND NOT EXISTS (SELECT 1 FROM posts WHERE posts.petId = pets.id)',
          legacyPetId
        );
      }

      // 2. Reuse existing owned Louie profile if present, retain his posts, and apply supplied details/photo
      const existingLouie =
        (await database.getFirstAsync<PetRow>(
          "SELECT * FROM pets WHERE isUserPet = 1 AND LOWER(TRIM(name)) = 'louie' " +
            "ORDER BY CASE WHEN id = 'pet-local' THEN 0 ELSE 1 END, createdAt, id LIMIT 1"
        )) ?? undefined;

      const louieSeedPet = INITIAL_SEEDED_PETS.find((p) => p.name === 'Louie')!;
      let louiePetId = 'pet-louie';

      if (existingLouie) {
        louiePetId = existingLouie.id;
        await database.runAsync(
          'UPDATE pets SET name = ?, species = ?, photoUri = ?, description = ?, isUserPet = 1 WHERE id = ?',
          louieSeedPet.name,
          louieSeedPet.species,
          louieSeedPet.photoUri,
          louieSeedPet.personality,
          louiePetId
        );
      } else {
        const occupied = await database.getFirstAsync<{ id: string }>(
          'SELECT id FROM pets WHERE id = ?',
          louiePetId
        );
        if (occupied) louiePetId = createLocalId('pet');
        await database.runAsync(
          'INSERT OR IGNORE INTO pets (id, name, species, photoUri, description, createdAt, isUserPet) ' +
            'VALUES (?, ?, ?, ?, ?, ?, 1)',
          louiePetId,
          louieSeedPet.name,
          louieSeedPet.species,
          louieSeedPet.photoUri,
          louieSeedPet.personality,
          louieSeedPet.createdAt
        );
      }

      // Insert Louie's bundled posts (retaining any existing posts the user already had for Louie)
      const louiePosts = INITIAL_SEEDED_POSTS.filter((p) => p.petId === 'pet-louie');
      for (const post of louiePosts) {
        await database.runAsync(
          'INSERT OR IGNORE INTO posts (id, petId, photoUri, description, createdAt) ' +
            'VALUES (?, ?, ?, ?, ?)',
          post.id,
          louiePetId,
          post.photoUri,
          post.caption,
          post.createdAt
        );
      }

      // 3. Insert the other seeded pets
      for (const pet of INITIAL_SEEDED_PETS) {
        if (pet.name === 'Louie') {
          continue;
        }
        await database.runAsync(
          'INSERT OR IGNORE INTO pets (id, name, species, photoUri, description, createdAt, isUserPet) ' +
            'VALUES (?, ?, ?, ?, ?, ?, ?)',
          pet.id,
          pet.name,
          pet.species,
          pet.photoUri,
          pet.personality,
          pet.createdAt,
          pet.isUserPet ? 1 : 0
        );
      }

      // 4. Insert the posts for the other pets
      for (const post of INITIAL_SEEDED_POSTS) {
        if (post.petId === 'pet-louie') {
          continue;
        }
        await database.runAsync(
          'INSERT OR IGNORE INTO posts (id, petId, photoUri, description, createdAt) ' +
            'VALUES (?, ?, ?, ?, ?)',
          post.id,
          post.petId,
          post.photoUri,
          post.caption,
          post.createdAt
        );
      }
      await database.runAsync('INSERT INTO app_migrations (id) VALUES (?)', 'personal-pets-v1');
      await database.runAsync('INSERT INTO app_migrations (id) VALUES (?)', 'louie-caption-v1');
      await updateSeedCaptions();
      await applySeedUpdatesV2();
    });
  })();

  try {
    await initializationPromise;
  } catch (error) {
    initializationPromise = undefined;
    databasePromise = undefined;
    throw error;
  }
}

export async function getPetSnapshot(): Promise<PetSnapshot> {
  await initializePetDatabase();
  const database = await getDatabase();
  const pets = await database.getAllAsync<PetRow>(
    'SELECT id, name, species, photoUri, description AS personality, createdAt, isUserPet FROM pets'
  );
  const posts = await database.getAllAsync<PetPost>(
    'SELECT id, petId, photoUri, description AS caption, createdAt FROM posts ORDER BY createdAt DESC'
  );
  const reactionRows = await database.getAllAsync<{ postId: string; value: ReactionKind }>(
    'SELECT postId, value FROM reactions'
  );

  return {
    pets: pets.map((pet) => ({ ...pet, isUserPet: Boolean(pet.isUserPet) })),
    posts,
    reactions: Object.fromEntries(
      reactionRows.map((reaction) => [reaction.postId, reaction.value])
    ),
  };
}

export async function saveLocalPetProfile(input: PetProfileInput, petId?: string): Promise<Pet> {
  await initializePetDatabase();
  const database = await getDatabase();
  const createdAt = new Date().toISOString();
  const trimmedPhotoUri = input.photoUri.trim();

  if (petId) {
    const existingBefore = await database.getFirstAsync<PetRow>(
      'SELECT id, name, species, photoUri, description AS personality, createdAt, isUserPet FROM pets WHERE id = ? AND isUserPet = 1',
      petId
    );
    if (!existingBefore) throw new Error('This pet profile could not be found.');
    const nextPhotoUri = trimmedPhotoUri || existingBefore.photoUri;
    const result = await database.runAsync(
      'UPDATE pets SET name = ?, species = ?, photoUri = ?, description = ? WHERE id = ? AND isUserPet = 1',
      input.name.trim(),
      input.species.trim(),
      nextPhotoUri,
      input.personality.trim(),
      petId
    );
    if (result.changes === 0) throw new Error('This pet profile could not be found.');
    const existing = await database.getFirstAsync<PetRow>(
      'SELECT id, name, species, photoUri, description AS personality, createdAt, isUserPet FROM pets WHERE id = ?',
      petId
    );
    if (existing) {
      return {
        ...existing,
        isUserPet: Boolean(existing.isUserPet),
      };
    }
    throw new Error('This pet profile could not be found.');
  }

  if (!trimmedPhotoUri) {
    throw new Error('A profile photo is required.');
  }

  const id = createLocalId('pet-user');
  await database.runAsync(
    'INSERT INTO pets (id, name, species, photoUri, description, createdAt, isUserPet) ' +
      'VALUES (?, ?, ?, ?, ?, ?, 1)',
    id,
    input.name.trim(),
    input.species.trim(),
    trimmedPhotoUri,
    input.personality.trim(),
    createdAt
  );

  return {
    id,
    name: input.name.trim(),
    species: input.species.trim(),
    photoUri: trimmedPhotoUri,
    personality: input.personality.trim(),
    createdAt,
    isUserPet: true,
  };
}

